from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent.parent))
from rendu import outils
base,p,c,h,w,table,liste,save=outils(2,8)
t=p('Le diagnostic positif utilise les critères révisés de 2016 repris par le Royal College of Physicians en 2022 et par la HAS en 2025. La DGN décrit bien le syndrome, mais son rappel des critères de 2010 ne constitue pas ici la version retenue pour la décision diagnostique.','f83-rcp-criteres-cadre','f83-has-differentiel','p83-myofascial-fibro')
t+=h('Les conditions sont cumulatives, avec une alternative interne')
t+=table(['Condition','Seuil ou règle','Interprétation'],[
['Douleur et sévérité',p('Le WPI est au moins égal à 7 et le SSS au moins égal à 5, OU le WPI est compris entre 4 et 6 et le SSS au moins égal à 9.','f83-rcp-criteres'),p('Le OU sépare deux combinaisons admissibles ; il ne permet pas de retenir seulement un WPI ou seulement un SSS.','f83-rcp-criteres')],
['Généralisation',p('La douleur intéresse au moins 4 des 5 régions définies.','f83-rcp-annexe2016'),p('Les douleurs de mâchoire, de thorax et d’abdomen ne comptent pas pour cette condition de généralisation.','f83-rcp-annexe2016')],
['Durée',p('Les symptômes sont présents à un niveau comparable depuis au moins 3 mois.','f83-rcp-criteres'),p('Une douleur aiguë diffuse ne suffit pas à satisfaire cette condition.','f83-rcp-criteres')],
['Portée clinique',p('Le diagnostic reste valable indépendamment d’autres diagnostics.','f83-rcp-annexe2016'),p('Une autre maladie importante peut néanmoins être présente et recevoir ses propres investigations.','f83-rcp-coexistence')]])
f=w('WPI : sites, période et régions',[
('Le WPI compte les sites douloureux durant la dernière semaine, avec un maximum de 19. Les régions supérieures gauche et droite comprennent chacune mâchoire, ceinture scapulaire, bras et avant-bras ; les régions inférieures gauche et droite comprennent chacune hanche ou région fessière/trochantérienne, cuisse et jambe.',['f83-rcp-annexe2016']),
('La région axiale comprend cou, haut du dos, bas du dos, thorax et abdomen. Pour vérifier la généralisation, le clinicien exclut les sites mâchoire, thorax et abdomen ; ces sites restent toutefois inclus dans le calcul du WPI lorsqu’ils sont douloureux.',['f83-rcp-annexe2016']),
('Le calcul des sites de la semaine et la condition de symptômes présents depuis au moins 3 mois répondent à deux questions différentes. Le clinicien conserve les deux temporalités au lieu de compter simplement tous les sites ayant été douloureux au cours de la vie.',['f83-rcp-annexe2016','f83-rcp-criteres'])])
t+=p('Le clinicien calcule le WPI avec '+f+' et distingue le nombre de sites du nombre de régions. Une multiplication des sites dans une seule région ne prouve pas la généralisation exigée.','f83-rcp-annexe2016')
t+=h('Le SSS conserve ses domaines et ses deux périodes de recueil')
t+=p('Le SSS cote séparément fatigue, difficultés de pensée ou de mémoire et réveil non réparateur durant la semaine écoulée. Chaque domaine reçoit 0 si absent, 1 si léger, 2 si modéré et 3 si sévère.','f83-rcp-sss')
t+=p('Le score ajoute un point pour chacun des éléments suivants sur les 6 derniers mois : douleur ou crampes du bas-ventre, dépression et céphalées. La somme totale du SSS se situe entre 0 et 12 ; cette règle ne se remplace pas par une liste indéfinie de symptômes somatiques.','f83-rcp-sss','f83-rcp-somme-sss')
t+=table(['Outil','Usage','Ce qu’il ne décide pas seul'],[
['WPI et SSS',p('Le clinicien vérifie les seuils, la généralisation et la durée.','f83-rcp-criteres','f83-rcp-annexe2016'),p('Un auto-questionnaire rempli sans interprétation clinique ne suffit pas.','f83-rcp-criteres-cadre')],
['FIRST',p('Au moins 5 réponses ou critères positifs sur 6 rendent la suspicion forte selon la HAS.','f83-has-orientation'),p('Le résultat n’est pas une confirmation ; un résultat négatif ou douteux exige de poursuivre la démarche selon le contexte.','f83-has-orientation','f83-has-depistage')],
['Questionnaire d’impact',p('La HAS propose le QIF pour documenter le retentissement de la fibromyalgie.','f83-has-suivi'),p('L’impact fonctionnel ne remplace pas les critères diagnostiques.','f83-has-suivi','f83-rcp-criteres')],
['PGI-C',p('L’échelle décrit le changement ressenti du fonctionnement, des symptômes ou de la qualité de vie.','f83-pgic'),p('Elle suit une évolution et ne mesure pas la présence initiale de la maladie.','f83-pgic','f83-rcp-criteres')]])
t+=h('Ce qui suffit, ce qui manque et ce qui impose une réévaluation')
t+=p('Un tableau cohérent remplissant les conditions, interprété lors d’une consultation et confronté aux diagnostics associés, permet un diagnostic clinique. Une douleur à la palpation, un bilan biologique normal ou une plainte de fatigue isolée ne suffit pas à eux seuls.','f83-rcp-criteres-cadre','f83-rcp-criteres','f83-rcp-coexistence')
t+=p('Le nombre historique de points douloureux à la pression n’est pas une condition ajoutée aux critères actuels retenus. La DGN précise que les critères modernes ont remplacé l’ancienne constatation de sensibilité à la palpation par les symptômes de fatigue, sommeil et cognition.','p83-myofascial-fibro','f83-rcp-criteres')
t+=p('Lorsqu’un score est proche du seuil, les fluctuations et les comorbidités peuvent compliquer l’interprétation. Le clinicien explique l’incertitude, propose un plan partagé et organise une nouvelle évaluation ; il ne prédit pas une progression inévitable vers la fibromyalgie.','f83-rcp-fluctuation')
save(t)

base,p,c,h,w,table,liste,save=outils(2,9)
t+=h('9.a — La référence est clinique')
t=p('Le diagnostic de référence est clinique : la HAS et le RCP ne proposent aucun biomarqueur spécifique de fibromyalgie. Les examens servent à identifier une maladie associée ou alternative, à analyser une anomalie clinique et à sécuriser un éventuel traitement.','f83-has-messages','f83-rcp-coexistence','aips-f83-dulox-contre-indications')
t+=p('L’IRM fonctionnelle de recherche, les anomalies des petites fibres et les observations de sensibilisation ne fournissent pas un examen de confirmation individuel. La DGN précise que ces constatations de sous-groupes ne peuvent pas être utilisées comme biomarqueurs diagnostiques.','p83-myofascial-fibro')
t+=h('9.b — Première intention : un bilan minimal orienté')
t+=p('La HAS recommande, quel que soit le résultat du FIRST, une NFS, une CRP, une TSH, des CK ou CPK et des transaminases. Cette prescription recherche notamment des affections inflammatoires, endocriniennes ou musculaires qui peuvent produire des symptômes proches.','f83-has-depistage')
t+=p('Le RCP propose également une glycémie, un bilan rénal et électrolytique et une vitesse de sédimentation dans son bilan de recherche des diagnostics différentiels. Le clinicien adapte ces compléments au contexte et aux traitements envisagés, sans présenter une batterie illimitée comme un préalable obligé à tout diagnostic.','f83-rcp-differentiel','f83-has-depistage')
t+=table(['Prescription','Interprétation et unités','Conduite'],[
['NFS',p('Le résultat est confronté aux intervalles du laboratoire et au contexte clinique ; la NFS ne mesure pas la sensibilisation douloureuse.','f83-has-depistage','f83-has-messages'),p('Une anomalie inexpliquée conduit à une recherche ciblée plutôt qu’à une attribution automatique au syndrome.','f83-has-depistage')],
['CRP, éventuellement VS selon le contexte',p('Une anomalie inflammatoire s’interprète avec les signes articulaires et systémiques.','f83-has-depistage','f83-rcp-differentiel'),p('Le clinicien explore la cause ; une inflammation et une fibromyalgie peuvent coexister.','f83-has-depistage')],
['TSH',p('La recherche d’une affection thyroïdienne appartient au bilan minimal, notamment devant fatigue et myalgies.','f83-has-depistage','p83-hypothyroidie'),p('Une anomalie conduit à une évaluation endocrinienne et à une réévaluation des symptômes après prise en charge.','f83-has-depistage')],
['CK ou CPK',p('Le clinicien confronte l’activité enzymatique à la norme du laboratoire, à l’effort et aux médicaments ; une valeur normale ne réfute pas toute myosite.','dgn83-laboratoire'),p('Une élévation ou une faiblesse objective motive une démarche musculaire ; une suspicion de rhabdomyolyse suit une voie urgente.','p83-myofascial-fibro','p83-rhabdo-clinique','p83-rhabdo-menace')],
['Transaminases',p('Le bilan contribue à la recherche de diagnostics associés et à la sécurité avant certains médicaments.','f83-has-depistage','aips-f83-dulox-contre-indications'),p('Une maladie hépatique entraînant une insuffisance hépatique contre-indique la duloxétine de référence.','aips-f83-dulox-contre-indications')],
['Créatinine et électrolytes selon le contexte',p('Le RCP inclut la fonction rénale et les électrolytes dans son bilan ; l’AIPS utilise la clairance de créatinine pour les restrictions rénales.','f83-rcp-differentiel','aips-f83-dulox-posologie'),p('Le clinicien distingue le paramètre rénal prescriptif de la simple étiquette « insuffisance rénale » et respecte la contre-indication en atteinte sévère.','aips-f83-dulox-contre-indications')]])
t+=p('Les extraits retenus ne fournissent pas une série complète de valeurs normales en unités SI pour ces analyses. Le clinicien utilise les intervalles du laboratoire concerné et ne remplace pas cette information par des chiffres mémorisés ou par une valeur universelle fictive.','f83-has-depistage','f83-rcp-differentiel')
t+=h('9.c — Situations spéciales et alternatives')
t+=table(['Situation','Choix raisonnable','Restriction décisive'],[
['Grossesse',p('La fibromyalgie n’exige pas une imagerie de confirmation ; si un autre diagnostic la rend nécessaire, le radiologue sélectionne la modalité utile.','f83-has-messages','f83-has-depistage'),p('L’ESUR réserve le gadolinium pendant la grossesse à une indication très forte, à la plus faible dose d’un produit macrocyclique ; le contexte rénal maternel ajoute une restriction absolue précisée en fenêtre.','pa82-esur-gadolinium-grossesse','pa82-esur-mere-renale')],
['Enfant ou adolescent',p('La Ligue décrit des cas rares chez les jeunes ; le clinicien ne transpose pas automatiquement un parcours thérapeutique adulte.','f83-ligue-epidemiologie','f83-has-bib'),p('L’AIPS de la duloxétine retenue n’indique pas son emploi avant 18 ans.','aips-f83-dulox-posologie')],
['DFGe inférieur à 30 mL/min/1,73 m²',p('L’ESUR identifie ce seuil comme un facteur de risque rénal pour certains usages de contraste iodé intravasculaire.','pa82-esur-renal'),p('Une imagerie sans produit ou une autre modalité est envisagée si elle répond à la question ; le clinicien ne confond pas cette règle avec la clairance utilisée par l’AIPS.','pa82-esur-alternative','aips-f83-dulox-contre-indications')],
['Antécédent de réaction au contraste',p('Le clinicien documente la réaction et discute une exploration qui n’utilise pas ce produit lorsque la question clinique peut être résolue autrement.','pa82-esur-hypersensibilite','pa82-esur-alternative'),p('La fibromyalgie seule ne justifie pas une exposition à un contraste pour rechercher une preuve de maladie.','f83-has-messages','f83-rcp-coexistence')],
['IRM impossible ou contre-indiquée',p('La DGN réserve notamment la TDM à des situations musculaires où l’IRM est contre-indiquée ; l’échographie peut aussi contribuer à une question neuromusculaire ciblée.','dgn83-imagerie'),p('En présence de drapeaux rouges neurologiques, les HUG recommandent une imagerie immédiate, idéalement IRM, avec TDM au minimum si nécessaire.','pa17-lomb22-urgence')]])
f=w('Contrastes : grossesse, allaitement et rein maternel',[
('Chez une mère enceinte ou allaitante présentant une atteinte rénale, l’ESUR demande de ne pas administrer de produit de contraste à base de gadolinium. La possibilité habituelle de poursuivre l’allaitement après un produit macrocyclique ne lève pas cette restriction maternelle.',['pa82-esur-mere-renale','pa82-esur-allaitement']),
('Si un contraste iodé est exceptionnellement nécessaire pendant la grossesse, l’ESUR prévoit un contrôle de la fonction thyroïdienne du nouveau-né pendant la première semaine. La prescription relève d’une question clinique réelle, distincte du diagnostic clinique de fibromyalgie.',['pa82-esur-iode-grossesse','f83-has-messages']),
('L’atteinte rénale, la réaction antérieure au produit et la faisabilité de modalités alternatives sont examinées avant l’injection. Une modalité sans contraste est privilégiée lorsqu’elle suffit à répondre à la question posée.',['pa82-esur-renal','pa82-esur-hypersensibilite','pa82-esur-alternative'])])
t+=p('Les restrictions de '+f+' restent applicables à une exploration d’un diagnostic associé. Elles ne créent aucune indication à imager systématiquement une fibromyalgie.','f83-has-depistage','f83-has-messages')
t+=h('9.d — Seconde intention guidée par les anomalies')
t+=p('Une suspicion de myosite peut conduire à une IRM musculaire, y compris lorsque les enzymes sont normales. La DGN rappelle cependant que des affections non inflammatoires peuvent produire des aspects proches ; une anomalie d’IRM ne devient donc pas automatiquement une myosite certaine.','dgn83-imagerie')
t+=p('L’échographie musculaire peut montrer une modification d’échogénicité ou une atrophie focale et compléter l’électrophysiologie dans une démarche neuromusculaire. Son interprétation dépend de l’examinateur et elle ne garantit pas la détection de toute pathologie ; elle ne constitue pas non plus un test de fibromyalgie.','dgn83-imagerie','p83-myofascial-fibro')
t+=p('Un déficit neurologique focal, une suspicion inflammatoire persistante ou une anomalie biologique inexpliquée conduit à un avis spécialisé et aux explorations adaptées. En revanche, le RCP déconseille de répéter les examens après diagnostic en l’absence de symptômes ou signes nouveaux.','f83-has-depistage','f83-rcp-differentiel')
t+=p('L’absence de biomarqueur ne justifie ni des examens successifs sans question clinique ni l’arrêt de toute vigilance. Le clinicien évalue chaque symptôme nouveau selon les standards appropriés, même lorsqu’une fibromyalgie est déjà reconnue.','f83-rcp-differentiel','f83-has-differentiel')
save(t)
